import sys,random,json,copy,traceback
sys.path.insert(0,'/workspace/submission')
sys.path.insert(0,'/tmp')
import engine, ref_engine

def rand_borders(rng):
    R=rng.randint(1,6)
    U=rng.randint(1,80)
    if R==1: return [0,U]
    cuts=sorted(rng.sample(range(1,U),min(R-1,U-1)))
    # if not enough interior, reduce R
    bs=[0]+cuts+[U]
    return bs

def make_run(rng, nops=120):
    M=rng.randint(1,4); L=rng.randint(1,3)
    borders=rand_borders(rng)
    kind=rng.choice(['fifo','sp','sff','wfq'])
    flows=list(range(1,rng.randint(2,6)))
    spec={'kind':kind}
    if kind=='sp': spec['levels']=[[f,rng.randint(0,50)] for f in flows]
    if kind=='wfq': spec['weights']=[[f,rng.randint(1,10)] for f in flows]
    run={'banks':M,'load_balancers':L,'fifo_bytes':rng.randint(1,80),'pifo_bytes':rng.randint(1,50),
         'refill_batch':rng.randint(1,6),'sample_period':rng.randint(1,8),'borders':borders,
         'policy':spec,'events':[]}
    nextid=1; saves=[]
    events=run['events']
    for _ in range(nops):
        choices=['enqueue','dequeue','sample','repartition','cancel','inspect','weight','save']
        if saves: choices+=['restore']*2
        c=rng.choice(choices)
        if c=='enqueue':
            e=['enqueue',nextid,rng.choice(flows),rng.randint(1,25),rng.randint(0,70)]
            nextid+=1; events.append(e)
        elif c=='dequeue':
            events.append(['dequeue',rng.randint(1,4)])
        elif c=='sample': events.append(['sample'])
        elif c=='repartition':
            events.append(['repartition',rand_borders(rng)])
        elif c=='cancel':
            events.append(['cancel',rng.randint(0,nextid+2)])
        elif c=='inspect':
            events.append(['inspect',rng.randint(0,nextid+2)])
        elif c=='weight':
            if kind=='wfq':
                events.append(['weight',rng.choice(flows),rng.randint(1,10)])
            else:
                events.append(['inspect',rng.randint(0,nextid+2)])
        elif c=='save':
            # distinct names <= maybe 8
            name=rng.choice(list(range(0,8)))
            events.append(['save',name]); saves.append(name)
        else:
            events.append(['restore',rng.choice(saves)])
    return run

rng=random.Random(12345)
for case in range(1000):
    run=make_run(rng,rng.randint(1,150))
    req={'runs':[run]}
    try:
        a=engine.run_request(copy.deepcopy(req))
        b=ref_engine.run_request(copy.deepcopy(req))
    except Exception:
        print('EXCEPTION case',case)
        print(json.dumps(req))
        traceback.print_exc()
        break
    if a!=b:
        print('MISMATCH case',case)
        print(json.dumps(req))
        # find first differing log
        la=a['runs'][0]['log']; lb=b['runs'][0]['log']
        print('log lens',len(la),len(lb))
        for i,(x,y) in enumerate(zip(la,lb)):
            if x!=y:
                print('first log diff at',i); print('ours',x); print('ref ',y); break
        else:
            if len(la)!=len(lb): print('len diff')
        if a['runs'][0]['state']!=b['runs'][0]['state']:
            print('state ours',json.dumps(a['runs'][0]['state']))
            print('state ref ',json.dumps(b['runs'][0]['state']))
        break
else:
    print('all ok')
